(5605391, 812749, 31664, '<td valign="top">Did you take this from the car? I had heaps of shots from in this tunnel and not one was usable,  should have cleaned my windscreen :)  Nice composition.</td>', 'Did you take this from the car? I had heaps of shots from in this tunnel and not one was usable,  should have cleaned my windscreen :)  Nice composition.', '2009-08-10 01:12:28.000000', NULL, 1),
(5605397, 812461, 63503, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2009-08-10 01:14:53.000000', NULL, 1),
(5605398, 812461, 6804, '<td valign="top">Remarkable Work!  Simply Stunning!</td>', 'Remarkable Work!  Simply Stunning!', '2009-08-10 01:14:58.000000', NULL, 1),
(5605405, 812694, 34938, '<td valign="top">nice tones and leading lines</td>', 'nice tones and leading lines', '2009-08-10 01:16:41.000000', NULL, 1),
