(5606436, 812919, 66398, '<td valign="top">I think a different title would have worked better. Like maybe something father-son-ish about the big great outdoors. The brightness at the top of the tunnel is a bit distracting.</td>', 'I think a different title would have worked better. Like maybe something father-son-ish about the big great outdoors. The brightness at the top of the tunnel is a bit distracting.', '2009-08-10 18:01:55.000000', NULL, 1),
(5606437, 812037, 66398, '<td valign="top">Just a tad bit more dof to get his feet and the edge of the "tunnel" in focus but still leave the rest oof.</td>', 'Just a tad bit more dof to get his feet and the edge of the "tunnel" in focus but still leave the rest oof.', '2009-08-10 18:01:59.000000', NULL, 1),
(5606438, 812694, 66398, '<td valign="top">This is an interesting geometry study.</td>', 'This is an interesting geometry study.', '2009-08-10 18:02:02.000000', NULL, 1),
(5606439, 812824, 66398, '<td valign="top">Too busy for the tunnel to stand out as the subject of the shot. Maybe a lower angle to get under the truss things?</td>', 'Too busy for the tunnel to stand out as the subject of the shot. Maybe a lower angle to get under the truss things?', '2009-08-10 18:02:06.000000', NULL, 1),
(5606440, 812482, 66398, '<td valign="top">Some added light to the interior so that the black isn''t the prominent portion of the photo would have made for a better shot imo. I realize with the title that maybe this was your intent but photographically I think it would look better if we saw some more of the interior as well.</td>', 'Some added light to the interior so that the black isn''t the prominent portion of the photo would have made for a better shot imo. I realize with the title that maybe this was your intent but photographically I think it would look better if we saw some more of the interior as well.', '2009-08-10 18:02:10.000000', NULL, 1),
(5606441, 812749, 66398, '<td valign="top">Not the best of the Mullum Mullum shots imo but not bad either. Must be a popular tunnel though as I''ve seen a few shots of it in this challenge.</td>', 'Not the best of the Mullum Mullum shots imo but not bad either. Must be a popular tunnel though as I''ve seen a few shots of it in this challenge.', '2009-08-10 18:02:13.000000', NULL, 1),
(5606442, 812912, 66398, '<td valign="top">Nice motion and composition.</td>', 'Nice motion and composition.', '2009-08-10 18:02:17.000000', NULL, 1),
