(5606456, 812496, 66398, '<td valign="top">too grainy and oof for my taste. good motion, just needs more of a focal spot I think.</td>', 'too grainy and oof for my taste. good motion, just needs more of a focal spot I think.', '2009-08-10 18:03:15.000000', NULL, 1),
(5606457, 812427, 66398, '<td valign="top">Way to get creative when you can''t get the real thing. Good job.</td>', 'Way to get creative when you can''t get the real thing. Good job.', '2009-08-10 18:03:19.000000', NULL, 1),
