(5606459, 812819, 66398, '<td valign="top">Looks like kind of a narrow steep staircase to me. Also looks like going down and not up even though common sense says otherwise.</td>', 'Looks like kind of a narrow steep staircase to me. Also looks like going down and not up even though common sense says otherwise.', '2009-08-10 18:03:26.000000', NULL, 1),
(5606460, 812800, 66398, '<td valign="top">I like the hues here.</td>', 'I like the hues here.', '2009-08-10 18:03:30.000000', NULL, 1),
(5606461, 812579, 66398, '<td valign="top">Not sure the yellow monotone is very helpful.</td>', 'Not sure the yellow monotone is very helpful.', '2009-08-10 18:03:33.000000', NULL, 1),
(5606462, 812702, 66398, '<td valign="top">Good idea and the composition is great. However, The photo is very flat. The colors are dull and the white balance is off quite a bit.</td>', 'Good idea and the composition is great. However, The photo is very flat. The colors are dull and the white balance is off quite a bit.', '2009-08-10 18:03:36.000000', NULL, 1),
(5606463, 812858, 66398, '<td valign="top">Kind of hard to figure this one out. Not sure having the light source in the shot is helping.</td>', 'Kind of hard to figure this one out. Not sure having the light source in the shot is helping.', '2009-08-10 18:03:40.000000', NULL, 1),
(5606464, 812769, 66398, '<td valign="top">This looks way over-processed to me.</td>', 'This looks way over-processed to me.', '2009-08-10 18:03:43.000000', NULL, 1),
(5606465, 812718, 66398, '<td valign="top">Kind of far reaching and I''m not a fan of the processing done here. Cute kid though.</td>', 'Kind of far reaching and I''m not a fan of the processing done here. Cute kid though.', '2009-08-10 18:03:48.000000', NULL, 1),
(5606466, 811822, 66398, '<td valign="top">The windshield is reflecting the dashboard and the highlights are too blown out for me.</td>', 'The windshield is reflecting the dashboard and the highlights are too blown out for me.', '2009-08-10 18:03:52.000000', NULL, 1),
(5606467, 812760, 66398, '<td valign="top">The car in the foreground is quite a distraction. I believe that would be a blocked off entrance to a maintenance access to the tunnel in which the blue car is headed. Or maybe that is the tunnel itself which was blocked off.</td>', 'The car in the foreground is quite a distraction. I believe that would be a blocked off entrance to a maintenance access to the tunnel in which the blue car is headed. Or maybe that is the tunnel itself which was blocked off.', '2009-08-10 18:03:57.000000', NULL, 1),
(5606468, 812864, 66398, '<td valign="top">This shot is quite flat and out of focus. I don''t see a cave/tunnel as the subject of the shot either.</td>', 'This shot is quite flat and out of focus. I don''t see a cave/tunnel as the subject of the shot either.', '2009-08-10 18:04:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5606470, 812892, 66398, '<td valign="top">Kind of a boring shot with so much darkness and the whites are blown out.</td>', 'Kind of a boring shot with so much darkness and the whites are blown out.', '2009-08-10 18:04:03.000000', NULL, 1),
