(5612543, 812912, 83313, '<td valign="top">I like it, but I also know it is hard to carry off a blur shot with high scoring broad appeal. I''ll be interested to see where this one ends up.</td>', 'I like it, but I also know it is hard to carry off a blur shot with high scoring broad appeal. I''ll be interested to see where this one ends up.', '2009-08-15 16:53:33.000000', NULL, 1),
(5612544, 812866, 83313, '<td valign="top">I like the tones and treatment, but the composition seems a bit awkward to me.</td>', 'I like the tones and treatment, but the composition seems a bit awkward to me.', '2009-08-15 16:54:15.000000', NULL, 1),
(5612545, 812819, 83313, '<td valign="top">Creepy looking treatment. Effective.</td>', 'Creepy looking treatment. Effective.', '2009-08-15 16:54:42.000000', NULL, 1),
