(5613208, 812193, 67258, '<td valign="top">My plan was to use a tunnel just like this, here in York; didn''t work out though.  This is far better than anything I could have taken.  Really good work.</td>', 'My plan was to use a tunnel just like this, here in York; didn''t work out though.  This is far better than anything I could have taken.  Really good work.', '2009-08-16 14:08:48.000000', NULL, 1),
(5613209, 812718, 67258, '<td valign="top">The idea is quite cool, but the end result is to far removed from photography, into the realms of digital art, for my tastes.</td>', 'The idea is quite cool, but the end result is to far removed from photography, into the realms of digital art, for my tastes.', '2009-08-16 14:09:38.000000', NULL, 1),
(5613240, 812911, 54645, '<td valign="top">Fantastic tone. I like the abstract nature of the image. One of my favorites in the challenge.</td>', 'Fantastic tone. I like the abstract nature of the image. One of my favorites in the challenge.', '2009-08-16 15:01:03.000000', NULL, 1),
