(5613252, 812872, 54645, '<td valign="top">Looks like the processing and emotion of Enzo. Lighting is emotive. I can''t stop laughing at the yellow arrow, well placed surprise! The blurred face looking at, then away from, the homeless fella really sells the image for me. Hope this makes the top 5.</td>', 'Looks like the processing and emotion of Enzo. Lighting is emotive. I can''t stop laughing at the yellow arrow, well placed surprise! The blurred face looking at, then away from, the homeless fella really sells the image for me. Hope this makes the top 5.', '2009-08-16 15:08:49.000000', NULL, 1),
(5613253, 812671, 54645, '<td valign="top">Good documentary photograph.</td>', 'Good documentary photograph.', '2009-08-16 15:09:15.000000', NULL, 1),
(5613255, 812496, 54645, '<td valign="top">Great idea. Like the BW, but not the artifacts in the foreground.</td>', 'Great idea. Like the BW, but not the artifacts in the foreground.', '2009-08-16 15:10:04.000000', NULL, 1),
