(5613320, 812461, 99448, '<td valign="top">OMG!!!, amazing colours, love the sky, this has to do well, <u><b>10</b></u> and <u><b>favorite</b></u></td>', 'OMG!!!, amazing colours, love the sky, this has to do well, 10 and favorite', '2009-08-16 17:00:48.000000', NULL, 1),
(5613327, 812577, 99448, '<td valign="top">wow, great colours, love the walls, <u><b>10</b></u> and it''s made my <u><b>favorites</b></u></td>', 'wow, great colours, love the walls, 10 and it''s made my favorites', '2009-08-16 17:05:29.000000', NULL, 1),
(5613364, 812861, 83313, '<td valign="top">Post-vote comment:<br/>I generally liked this entry and I gave it a 6. Nice leading composition, good details, and the one area of bright color draws me to it. My nitpick is that the close area to the bottom left, and some of the cavern floor, appears to be lit far differently than the rest of the scene and it does not come off as well as the rest of the image. It looks like utilitarian lighting. Probably your flashlight. It really is hard to tell how these long exposures will come off until you see the result later. I suspect that aspect of the lighting may be the main reason for any low votes this is getting.</td>', 'Post-vote comment:I generally liked this entry and I gave it a 6. Nice leading composition, good details, and the one area of bright color draws me to it. My nitpick is that the close area to the bottom left, and some of the cavern floor, appears to be lit far differently than the rest of the scene and it does not come off as well as the rest of the image. It looks like utilitarian lighting. Probably your flashlight. It really is hard to tell how these long exposures will come off until you see the result later. I suspect that aspect of the lighting may be the main reason for any low votes this is getting.', '2009-08-16 18:02:13.000000', NULL, 1),
(5613430, 812566, 90474, '<td valign="top">Good exposure, without letting the light from the entrance overpower the scene.</td>', 'Good exposure, without letting the light from the entrance overpower the scene.', '2009-08-16 20:37:33.000000', NULL, 1),
(5613434, 812685, 90474, '<td valign="top">A little too far with the processing.</td>', 'A little too far with the processing.', '2009-08-16 20:45:26.000000', NULL, 1),
(5613440, 812844, 86447, '<td valign="top">Oh WOw... well done.  I hope this is doing well for you!   (not voting)</td>', 'Oh WOw... well done.  I hope this is doing well for you!   (not voting)', '2009-08-16 20:52:25.000000', NULL, 1),
